// ✅ components/PostCard.jsx
import React, { useState } from 'react';
import { Link } from 'react-router-dom';

function PostCard({ post, isLoggedIn }) {
    const [likes, setLikes] = useState(0);
    const [dislikes, setDislikes] = useState(0);
    const [liked, setLiked] = useState(false);
    const [disliked, setDisliked] = useState(false);

    const handleLike = (e) => {
        e.preventDefault();
        if (!isLoggedIn) return alert("Please login");
        if (!liked) {
            setLikes(likes + 1);
            if (disliked) {
                setDislikes(dislikes - 1);
                setDisliked(false);
            }
            setLiked(true);
        } else {
            setLikes(likes - 1);
            setLiked(false);
        }
    };

    const handleDislike = (e) => {
        e.preventDefault();
        if (!isLoggedIn) return alert("Please login");
        if (!disliked) {
            setDislikes(dislikes + 1);
            if (liked) {
                setLikes(likes - 1);
                setLiked(false);
            }
            setDisliked(true);
        } else {
            setDislikes(dislikes - 1);
            setDisliked(false);
        }
    };

    return (
        <div style={{ border: '1px solid #ccc', borderRadius: '10px', padding: '20px', textAlign: 'center', position: 'relative', color: '#000' }}>
            <Link to={`/post/${post.id}`} style={{ textDecoration: 'none', color: 'inherit' }}>
                <img src={post.imageUrl} alt={post.title} style={{ width: '100%', height: '200px', objectFit: 'cover', borderRadius: '5px' }} />
                <h3 style={{ margin: '15px 0 10px' }}>{post.title}</h3>
                {/* <p style={{ color: '#555', fontSize: '14px' }}>{post.content}</p> */}
            </Link>

            <div style={{ position: 'absolute', bottom: '10px', right: '10px', display: 'flex', alignItems: 'center' }}>
                <div onClick={handleLike} style={{ cursor: 'pointer', marginRight: '10px', display: 'flex', alignItems: 'center' }}>
                    <span style={{ fontSize: '18px', color: liked ? 'red' : 'gray', marginRight: '6px' }}>{liked ? '❤️' : '🤍'}</span>
                    <span>{likes}</span>
                </div>
                <div onClick={handleDislike} style={{ cursor: 'pointer', display: 'flex', alignItems: 'center' }}>
                    <span style={{ fontSize: '18px', color: disliked ? '#666' : 'gray', marginRight: '6px' }}>👎</span>
                    <span>{dislikes}</span>
                </div>
            </div>
        </div>
    );
}

export default PostCard;
